    const w = workers.get(worker);
    if (!w) return refuse(`unknown worker ${worker}`);
    if (w.status !== 'busy') return refuse(`worker ${worker} is not busy`);
    w.status = 'idle';
    report(worker, outcome);
    return ok();
  };

