    const w = workers.get(id)!;
    if (msg.action === 'Assign') {
      if (w.status === 'idle') w.status = 'busy';
    } else if (msg.action === 'Abort') {
      if (w.status === 'busy') {
        w.status = 'idle';
        report(id, 'cancelled');
      }
    }
  };

  const dispatch = (msg: Message): void => {
    if (msg.to === RUN) onRun(msg);
    else if (workers.has(msg.to)) onWorker(msg.to, msg);
  };

