    if (w.status !== 'busy') return refuse(`worker ${worker} is not busy`);
    w.status = 'idle';
    report(worker, outcome);
    return ok();
  };

  return {
    async inFlight() {
      return queue.map((m) => ({ ...m, data: { ...m.data } }));
    },
    async deliver(id: string) {
      const i = queue.findIndex((m) => m.id === id);
      if (i < 0) return;
      const [msg] = queue.splice(i, 1);
