import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { CreateHost } from '../host.ts';
const _c: CreateHost = createHost;

const fresh = { retried0: false, retried1: false };

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', ...fresh, processed: 0 });
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.start()).ok, true);
  assert.equal((await h.start()).ok, false);
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  assert.equal(await h.worker('x'), null);
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workDone('worker0', 1); await h.workDone('worker1', 2);
  const reports = await h.inFlight();
  assert.deepEqual(reports.map((m) => m.data).sort((a, b) => (a.task as number) - (b.task as number)),
    [{ task: 0, outcome: 'completed', items: 1 }, { task: 1, outcome: 'completed', items: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', ...fresh, processed: 3 });
});

test('cancel races completion', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 2);
  assert.equal((await h.cancel()).ok, true);
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  const aborts = msgs.filter((m) => m.action === 'Abort');
  assert.equal(aborts.length, 2);
  for (const m of aborts) await h.deliver(m.id);
  assert.equal((await h.run()).status, 'cancelling');
  const cancelled = (await h.inFlight()).find((m) => m.data.outcome === 'cancelled');
  assert.deepEqual(cancelled?.data, { task: 1, outcome: 'cancelled', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled', ...fresh, processed: 2 });
});

test('failure is retried once, then recorded', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1');
  assert.deepEqual((await h.inFlight())[0].data, { task: 1, outcome: 'failed', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: false, retried1: true, processed: 0 });
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  await h.workDone('worker0', 1); await h.deliverAll();
  assert.equal((await h.run()).status, 'running');
  await h.workFailed('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'completed', task1: 'failed', retried0: false, retried1: true, processed: 1 });
});

test('timeout fails the task, aborts the worker, ignores late report', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start(); await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.workDone('worker0', 2);
  assert.equal((await h.taskTimeout(0)).ok, true);
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', ...fresh, processed: 0 });
  await h.deliverAll();
  assert.equal((await h.run()).task0, 'failed');
  assert.equal((await h.run()).processed, 0);
  await h.workDone('worker1', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', ...fresh, processed: 1 });
  assert.equal((await h.taskTimeout(1)).ok, false);
});

test('timeout while cancelling', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.cancel();
  assert.equal((await h.taskTimeout(1)).ok, true);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'cancelled', task1: 'failed', ...fresh, processed: 0 });
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('retry then success completes', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliverAll();
  await h.workDone('worker0', 2); await h.workDone('worker1', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: true, retried1: false, processed: 4 });
});

test('failure while cancelling is recorded, not retried', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', ...fresh, processed: 0 });
});

